export function paletteControls(values){if(!values.length)return '';const type=values[0].type;if(values.some(v=>v.type!==type))return '<p>Seleccioná construcciones del mismo tipo para editar sus parámetros juntos.</p>';const fields=(specs[type]||[]).map(([key,label,defaultValue,...rest])=>{const options=Array.isArray(defaultValue)?[defaultValue,...rest]:null,get=o=>key==='pathLength'?o._pathLength:key==='sliderPercent'?(o.slider??.12)*100:key==='width'?(o.thickness??o.width??defaultValue):(o[key]??(options?options[0][0]:defaultValue)),first=get(values[0]),mixed=values.some(o=>get(o)!==first),attr=`data-construction-param="${key}"`;return `<div class="field ${options?'full':''}"><label>${label}${mixed?' · Mixto':''}</label>${options?`<select ${attr}>${mixed?'<option value="" selected disabled>Mixto</option>':''}${options.map(([v,n])=>`<option value="${v}" ${!mixed&&String(v)===String(first)?'selected':''}>${n}</option>`).join('')}</select>`:`<input type="number" step="0.1" ${attr} value="${mixed?'':Number(first).toFixed(2).replace(/\.?0+$/,'')}" placeholder="${mixed?'Mixto':''}">`}</div>`;});for(const key of ['offset','spacing','intensity','length','amount']){if(!specs[type]?.some(s=>s[0]===key))continue;const v=values[0][key]??0;fields.push(`<label class="field full">${({offset:'Offset',spacing:'Separación',intensity:'Intensidad',length:'Largo',amount:'Curvatura'}[key])}<input type="range" data-construction-param="${key}" min="${key==='amount'?-100:0}" max="${key==='spacing'?50:100}" step=".1" value="${v}"></label>`);}fields.push(`<div class="field full"><label>Color</label><input type="color" data-construction-param="stroke" value="${esc(values[0].stroke||'#444b49')}"></div>`);return `<div class="fields">${fields.join('')}</div>`;}
